Clear[f, F, y, Y, ys, t, s]
f[t_] = Piecewise[{{0, t < 0}, {Sin[2 t], 0 <= t < 3}, {t - 3, t >= 3}}];
ecdif = y''[t] + y[t] == f[t] + 5;
(* se transforma la ecuación y se ponen las condiciones iniciales *)
ec1 = LaplaceTransform[ecdif, t, s] /. {y[0] -> 10, y'[0] -> 0};
sol1 = Solve[ec1, LaplaceTransform[y[t], t, s]];
Y[s_] = LaplaceTransform[y[t], t, s] /. Flatten[sol1];   (* Y(s) = TL de la solución *)
Y[2.3]

