Clear[f, int, u, x, y, C1]
(* primer paso: (Dx - 2 Dy - 1) u = y E^(-2 x)  ->  a = 1, b = -2, c = -1 *)
a1 = 1; b1 = -2; c1 = -1; f[x_, y_] = y*Exp[-2 x];
int[x_, C1_] = Exp[-c1*x/a1]/a1*Integrate[Exp[c1*x/a1]*f[x, (C1 + b1*x)/a1], x];
u[x_, y_] = int[x, a1*y - b1*x] // Simplify   (* se deshace la característica C1 = a y - b x *)
u[0, 1] // N

Clear[f, int, u, x, y, C1]
(* primer paso: (Dx - 2 Dy - 1) u = y E^(-2 x)  ->  a = 1, b = -2, c = -1 *)
a1 = 1; b1 = -2; c1 = -1; f[x_, y_] = y*Exp[-2 x];
int[x_, C1_] = Exp[-c1*x/a1]/a1*Integrate[Exp[c1*x/a1]*f[x, (C1 + b1*x)/a1], x];
u[x_, y_] = int[x, a1*y - b1*x] // Simplify   (* se deshace la característica C1 = a y - b x *)
(* segundo paso: (Dy + 1) z = u. No hay Dx: se integra en y con x fija *)
b2 = 1; c2 = 1;
z[x_, y_] = Exp[-c2*y/b2]/b2*Integrate[Exp[c2*y/b2]*u[x, y], y] // Simplify
z[0.5, 2]

Clear[a, L, nau, f, psi1, psi2, phi1, phi2, u0, du0, u3, g, u10, du3, du10, An, Bn, u1, gn, u2, u, x, t, tau]
(* datos. a con punto decimal: todo se calcula en numérico y va mucho más rápido *)
a = Sqrt[3.]; L = 5; nau = 5;
f[x_, t_] = 1/5*x*(5 - x);
psi1[t_] = 2*Sin[3*t]; psi2[t_] = 0;
phi1[x_] = 3*(UnitStep[x - 2] - UnitStep[x - 3]); phi2[x_] = 0;
(* plantilla 9.4.1: u = u1 + u2 + u3 *)
u0[x_] = phi1[x]; du0[x_] = phi2[x];
u3[x_, t_] = psi1[t] + (x/L)*(psi2[t] - psi1[t]);
g[x_, t_] = f[x, t] - D[u3[x, t], {t, 2}];
u10[x_] = u0[x] - u3[x, 0];
du3[x_, t_] = D[u3[x, t], t];
du10[x_] = du0[x] - du3[x, 0];
An[n_Integer] := (2/L) Integrate[u10[x]*Sin[n*Pi*x/L], {x, 0, L}]
Bn[n_Integer] := (2/(n*Pi*a)) Integrate[du10[x]*Sin[n*Pi*x/L], {x, 0, L}]
u1[x_, t_] := Sum[(An[n]*Cos[n*Pi*a*t/L] + Bn[n]*Sin[n*Pi*a*t/L])*Sin[n*Pi*x/L], {n, 1, nau}]
gn[n_Integer, t_] := (2/L) Integrate[g[x, t]*Sin[n*Pi*x/L], {x, 0, L}]
u2[x_, t_] := Sum[(L/(n*Pi*a)) Integrate[gn[n, tau]*Sin[n*Pi*a*(t - tau)/L], {tau, 0, t}]*Sin[n*Pi*x/L], {n, 1, nau}]
u[x_, t_] = u1[x, t] + u2[x, t] + u3[x, t];
u[3, 6] // N

